from google.cloud import translate_v2 as translate

def translation_client():
    client = translate.Client()
    return client

def normalize_response(response):
    return response['translatedText']

from bs4 import BeautifulSoup
from.translation_client import translation_client, normalize_response

def translate_markup(markup, target_language):
    soup = BeautifulSoup(markup, 'html.parser')
    for tag in soup.find_all(text=True):
        if tag.parent.name not in ['style', 'script', '[document]', 'head', 'title']:
            translated_text = translation_client().translate(tag, target_language=target_language)
            tag.replace_with(translated_text['translatedText'])
    return str(soup)

from.translation_client import translation_client, normalize_response

def translate_dictionary_values(dictionary, target_language):
    client = translation_client()
    translated_dict = {}
    for key, value in dictionary.items():
        translated_value = client.translate(value, target_language=target_language)
        translated_dict[key] = normalize_response(translated_value)
    return translated_dict

from.translation_client import translation_client

def quality_summary(text, target_language):
    client = translation_client()
    translation = client.translate(text, target_language=target_language)
    quality_issues = {
        'original': text,
        'translated': translation['translatedText'],
        'issues': 'Placeholder for quality issues'
    }
    return quality_issues
